function init(){defaults({gap:15,day:'周六'})}init();
const mins=s=>{const[h,m]=s.split(':').map(Number);return h*60+m},clock=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
function conflicts(t){return state.tasks.filter(x=>x.id!==t.id&&x.day===t.day&&mins(x.start)<mins(t.end)+p.gap&&mins(t.start)<mins(x.end)+p.gap)}
function editTask(id){const t=state.tasks.find(x=>x.id===id);editModal(t?'调整活动':'安排一件想做的事',field('活动名称','name','text',t?.name||'','required maxlength="40" placeholder="例如：去公园观察昆虫"')+select('哪一天','day',['周六','周日'],t?.day||p.day)+`<div class="fields">${field('开始时间','start','time',t?.start||'10:00','required min="08:00" max="19:59"')}${field('结束时间','end','time',t?.end||'11:00','required min="08:01" max="20:00"')}</div>`+select('这件事有多重要','priority',['高','中','低'],t?.priority||'中'),v=>{if(mins(v.end)<=mins(v.start)){toast('结束时间要晚于开始时间');return false}const next={...v,id:t?.id||uid(),done:t?.done||false};if(t)Object.assign(t,next);else state.tasks.push(next);p.day=v.day;commit(conflicts(next).length?'已保存，请留意日程中的冲突提醒':'活动已安排好')});if(t){$('#edit-form').insertAdjacentHTML('beforeend',btn('删除这项活动','delete-event','danger'));on('delete-event',()=>{state.tasks=state.tasks.filter(x=>x.id!==id);closeModal();commit('已删除，可撤销')})}}
function render(){nav();const tasks=state.tasks.filter(t=>t.day===p.day).sort((a,b)=>a.start.localeCompare(b.start));const total=tasks.reduce((a,t)=>a+mins(t.end)-mins(t.start),0);const tabs=`<div class="segmented">${['周六','周日'].map(d=>`<button data-day="${d}" class="${d===p.day?'selected':''}">${d}</button>`).join('')}</div>`;
if(active===0){$('#app').innerHTML=`<div class="two-col"><div>${tabs}${hero('给周末一点安排',`${tasks.length}<small>件想做的事</small>`,`${p.day} · 活动合计 ${total} 分钟`,'clock')}${heading('我的时间轴',btn('＋ 安排活动','add',''))}<div class="timeline">${list(tasks,t=>`<article class="time-row"><div class="time-label">${t.start}</div><div class="time-event"><div class="between"><h3>${esc(t.name)}</h3>${check('done',t.id,t.done,(t.done?'撤销':'完成')+t.name)}</div><p>${t.start} – ${t.end} · ${mins(t.end)-mins(t.start)} 分钟</p>${conflicts(t).length?'<p class="warning notice">与其他活动相撞，或休息不足。试着调整时间。</p>':''}<div class="row"><span class="pill">${t.done?'已完成':t.priority+'优先'}</span><button data-edit="${t.id}">调整</button></div></div></article>`)}</div></div><aside class="stack"><section class="card"><div class="tile-icon">${icon('leaf')}</div><h3 style="margin:16px 0 10px">空白，也是计划的一部分</h3><p class="hint">活动之间留 ${p.gap} 分钟休息。给发呆、聊天和临时的小惊喜留一点空间。</p>${btn('看看空闲时段','free','secondary full')}</section><div class="subtle">规划范围：08:00–20:00。优先级帮助你取舍，不会自动移动活动。</div></aside></div>`;on('add',()=>editTask());on('free',()=>go(1));actions('edit',editTask);actions('done',id=>{const t=state.tasks.find(x=>x.id===id);t.done=!t.done;commit()})}
if(active===1){let cursor=480;const gaps=[];for(const t of tasks){if(mins(t.start)>cursor)gaps.push([cursor,mins(t.start)]);cursor=Math.max(cursor,mins(t.end)+p.gap)}if(cursor<1200)gaps.push([cursor,1200]);$('#app').innerHTML=`<div class="screen-body">${tabs}${heading('可以自由安排的时间')}${list(gaps,([a,b])=>`<div class="card between"><div><h3>${clock(a)} – ${clock(b)}</h3><p class="hint">${b-a} 分钟留白</p></div><span class="tile-icon">${icon('leaf')}</span></div>`)}<section class="card" style="margin-top:22px"><form id="gap" class="stack">${field('每项活动后休息几分钟','gap','number',p.gap,'required min="0" max="120"')}<button class="primary">更新休息时间</button></form></section></div>`;form('gap',v=>{p.gap=+v.gap;commit()})}
if(active===2){$('#app').innerHTML=`<div class="screen-body">${heading('周末小回顾')}${hero('一步一步完成',`${state.tasks.filter(x=>x.done).length}<small>/ ${state.tasks.length} 件</small>`,'计划可以调整，完成的小事值得被记住。','clock')}<div class="list">${list(state.tasks,t=>`<div class="list-item"><span class="tile-icon">${icon(t.done?'check':'clock')}</span><div class="content"><strong>${esc(t.name)}</strong><p>${t.day} · ${t.done?'已经完成':'还没完成'}</p></div></div>`)}</div></div>`}actions('day',d=>{p.day=d;render()});}
shell([['日程','clock'],['留白','leaf'],['回顾','list']]);render();
